<div class="form-grid"><x-field name="name" label="Name" :value="$source['name'] ?? ''" required maxlength="300" /><x-field name="url" type="url" label="YouTube channel or playlist URL" :value="$source['url'] ?? ''" required /></div>
<x-destination media-type="podcast" :selected-library="$source['libraryId'] ?? ''" :selected-folder="$source['libraryFolderId'] ?? ''" />
<div class="form-grid"><label class="field"><span>Download format</span><select name="mode"><option value="video" @selected(($source['mode'] ?? 'video') === 'video')>Video · listen or watch</option><option value="audio" @selected(($source['mode'] ?? '') === 'audio')>Audio only · use less storage</option></select></label><x-field name="intervalMinutes" label="Check every (minutes)" type="number" :value="$source['intervalMinutes'] ?? 360" min="15" max="10080" required /><x-field name="maxItems" label="Newest items to check" type="number" :value="$source['maxItems'] ?? 20" min="1" max="100" required /><x-field name="retentionDays" label="Keep downloaded originals (days)" type="number" :value="$source['retentionDays'] ?? 0" min="0" max="3650" hint="0 keeps everything. Expired originals are removed; listening history remains." required /><x-field name="startDate" label="Only published on or after" type="date" :value="$source['startDate'] ?? ''" /></div>
<label class="check"><input type="checkbox" name="enabled" value="1" @checked(old('enabled', $source['enabled'] ?? true))>Automatically check for new episodes</label>
